import { addCollection } from 'iconify-icon';
import collection from './iconoteka.generated.json' with { type: 'json' };

// <iconify-icon> fetches unknown icons from the Iconify API, which has no
// Iconoteka set, so the project's icons are registered from the bundled
// collection before any element renders. Import this module, not
// 'iconify-icon', wherever icons are used. The collection is generated by
// scripts/build-icons.ts.
addCollection(collection);
